        <li><strong>アイメイク：</strong>最低2週間禁止（ファンデーション等は1週間後から可）</li>
        <li><strong>飲酒：</strong>最低1週間は禁止（術後1ヶ月まで少量に抑える）</li>
        <li><strong>喫煙：</strong>最低1ヶ月禁煙推奨（治癒を大きく遅延させる）</li>
